#include "fates/graphics/battle_camera.hpp"
#include "fates/detail/principal_camera_runtime.hpp"
#include <algorithm>
BattleCamera::BattleCamera(){ResetInput();ResetUnitPos();} BattleCamera::~BattleCamera(){states_.ClearState();} void BattleCamera::ResetInput(){input_.Reset();} bool BattleCamera::ChangeMode(CameraConst::Mode m,bool force,bool){if(!force&&!CanChangeMode())return false;if(m==mode_&&!force)return false;if(CameraState*s=fates::decomp_detail::CreateBattleCameraState(m))states_.ChangeState(s);mode_=m;focusUnit_=-1;if(auto*s=states_.GetCurrentState())s->ChangeToFocus(-1);return true;} void BattleCamera::CameraShake(){fates::decomp_detail::BattleCameraShake(*this);} bool BattleCamera::ChangeFocus(int id,bool force){if(!force&&!CanChangeMode())return false;if(id==focusUnit_&&!force)return true;if(auto*s=states_.GetCurrentState())s->ChangeToFocus(id);focusUnit_=id;return true;} void BattleCamera::ResetUnitPos(){for(auto&p:unitPos_)p={};UpdateUnitPos();} void BattleCamera::UpdateUnitPos(){fates::decomp_detail::BattleCameraUpdateUnits(*this);} void BattleCamera::Tick(){if(!active_)return;UpdateUnitPos();states_.Tick();const auto type=fates::decomp_detail::BattleCameraInputAllowed(*this)?CameraInput::Type::Rotate:CameraInput::Type::None;input_.Tick(type,1.0f,0.0f,0.0f);CameraShake();Update();} void BattleCamera::Quake(float a,int frames){if(frames<0)frames=0x7fffffff;quakeAmplitude_=a;quakeFrames_=(a==0.0f)?0:frames;} void BattleCamera::Update(){fates::decomp_detail::BattleCameraApply(*this);} bool BattleCamera::CanChangeMode()const{return fates::decomp_detail::BattleCameraCanChangeMode(*this);} float BattleCamera::GetFocusFactor()const{return fates::decomp_detail::BattleCameraFocusFactor(*this);} float BattleCamera::GetFocusLength()const{return fates::decomp_detail::BattleCameraFocusLength(*this);}
